"""RoboPaint 福: camera-calibrated brush control. No reset or privileged state.
Commands are recorded in actions.jsonl; plans contain brush-tip waypoints.
"""
import sys, json, time, pathlib
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
ROOT=pathlib.Path('/app/output')
ZP=.0202
QUAT=[0,1,0,0]
class Painter:
 def __init__(self):
  self.r=Robot();self.o=self.r.get_obs(cameras=[]);self.pos=np.array(self.o.meta['proprio']['now'][7:10]);self.rows=[]
 def move(self,xyz,speed=.035,hold=0):
  xyz=np.array(xyz);n=max(1,int(np.ceil(np.linalg.norm(xyz-self.pos)/speed/.05)))
  self.rows.extend([list(p)+QUAT for p in np.linspace(self.pos,xyz,n+1)[1:]])
  self.rows.extend([list(xyz)+QUAT]*int(round(hold/.05)));self.pos=xyz
 def run(self,name,cams=['practice_cam','canvas_cam'],fps=2):
  for i in range(0,len(self.rows),190):
   a=self.rows[i:i+190]
   with open(ROOT/'actions.jsonl','a') as f:f.write(json.dumps({'name':name,'actions':a,'dt':.05})+'\n')
   out=self.r.submit('ee_pose',a,dt=.05,cameras=cams,video='none',video_fps=fps,note=name)
   if out.stopped or out.meta.get('plan',{}).get('ik_failed_steps',0):print('CHECK',out.meta,flush=True)
   d=ROOT/'runs'/f'{out.meta["calls"]:04d}_{name}';out.save(str(d))
   for k,v in out.last.items():Image.fromarray(v).save(ROOT/f'latest_{k}.png')
   print(name,i,len(self.rows),'tip',out.meta['proprio']['now'][7:10],'time_left',out.meta.get('time_left_s'),'plan',out.meta.get('plan'),flush=True)
  self.rows=[]
 def dip(self):
  self.move([*self.pos[:2],.08]);self.move([-.10,.15,.08],.09);self.move([-.10,.15,.024],.02,hold=.6);self.move([-.10,.15,.08],.03)
 def park(self):
  self.move([*self.pos[:2],.07]);self.move([-.25,.05,.09],.08,hold=.5)
 def practice(self):
  self.dip()
  for i,dep in enumerate([.0005,.001,.002,.0035,.005,.008]):
   x=-.015-i*.027
   self.move([x,-.155,.06],.07);self.move([x,-.155,ZP-dep],.015,hold=.3)
   self.move([x,-.212,ZP-dep],.015,hold=.2);self.move([x,-.212,.055],.025)
  self.park();self.run('calibrate')
if __name__=='__main__':
 p=Painter()
 if sys.argv[1]=='practice':p.practice()
 elif sys.argv[1]=='plan':
  plan=json.load(open(sys.argv[2]));
  for seg in plan:
   if seg.get('dip'):p.dip()
   for q in seg.get('moves',[]):p.move(q[:3],q[3] if len(q)>3 else .02,q[4] if len(q)>4 else 0)
   if seg.get('park'):p.park()
   p.run(seg['name'])
 elif sys.argv[1]=='observe':
  o=p.r.get_obs(cameras=['canvas_cam','practice_cam','scene_cam','side_cam'],depth=True);o.save(str(ROOT/'observe'))
  for k,v in o.last.items():Image.fromarray(v).save(ROOT/f'latest_{k}.png')
  print(p.r.status())
